(7268, 37, 'Given that log₃ 27 = 2x + 1, find the value of x.', '0', '1', '2', '3', 'B'),
(7269, 37, 'Solve 6x² = 5x - 1.', 'x = 2, 3', 'x = 0, 3', 'x = 1/2, 1/3', 'x = 1/2, -1/3', 'C'),
